1	package snapshot
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"reflect"
8		"testing"
9		"time"
10	
11		"example.com/tally/internal/money"
12		"example.com/tally/internal/store"
13	)
14	
15	func TestSaveAndLoad(t *testing.T) {
16		now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
17		st := store.New()
18		o, _ := st.CreateOrg("A", store.OrgTeam, "Europe/Berlin", 1900, now)
19		u, _ := st.CreateUser("ann@example.com", "Ann", now)
20		_, _ = st.AddMember(o.ID, u.ID, store.RoleOwner, now)
21		k, _ := st.CreateAPIKey(o.ID, u.ID, "k", now)
22		c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
23		_, _ = st.CreateInvoice(store.Invoice{OrgID: o.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []store.Line{{Description: "x", Quantity: 2, UnitAmount: 150}}}, now)
24	
25		path := filepath.Join(t.TempDir(), "tally.json")
26		if err := Save(st, path, now); err != nil {
27			t.Fatal(err)
28		}
29		got, err := Load(path)
30		if err != nil {
31			t.Fatal(err)
32		}
33		if !reflect.DeepEqual(got.Export(), st.Export()) {
34			t.Fatal("the loaded store differs from the saved one")
35		}
36		if _, ok := got.APIKeyByToken(k.Token); !ok {
37			t.Fatal("API keys do not work after a reload")
38		}
39	}
40	
41	func TestLoadVersion1(t *testing.T) {
42		st, err := Load(filepath.Join("testdata", "v1.json"))
43		if err != nil {
44			t.Fatal(err)
45		}
46		o, ok := st.Org("org_000001")
47		if !ok || o.Plan != store.OrgFree || o.TimeZone != "UTC" || o.TaxRateBP != 825 {
48			t.Fatalf("org = %+v", o)
49		}
50		c, ok := st.Customer(o.ID, "cus_000004")
51		if !ok || c.Name != "Jane Doe" || c.Email != "jane@example.com" {
52			t.Fatalf("customer = %+v", c)
53		}
54		p, ok := st.Plan(o.ID, "plan_000005")
55		if !ok || p.Currency != money.USD || p.UnitAmount != 1999 || p.UsageType != store.Licensed || !p.Active {
56			t.Fatalf("plan = %+v", p)
57		}
58		if k, ok := st.APIKeyByToken("tly_00000000000000000000000000000003"); !ok || k.UserID != "usr_000002" {
59			t.Fatalf("key = %+v", k)
60		}
61		inv, ok := st.Invoice(o.ID, "in_000007")
62		if !ok || inv.Lines[0].UnitAmount != 1999 || inv.Status != store.InvoicePaid {
63			t.Fatalf("invoice = %+v", inv)
64		}
65		next, err := st.CreateCustomer(o.ID, "New", "new@example.com", time.Now())
66		if err != nil || next.ID == "cus_000004" || next.ID <= "cus_000008" {
67			t.Fatalf("the next ID %q reuses an old one: %v", next.ID, err)
68		}
69	}
70	
71	func TestLoadRefusesUnknownVersions(t *testing.T) {
72		path := filepath.Join(t.TempDir(), "future.json")
73		if err := os.WriteFile(path, []byte(`{"version": 9, "state": {}}`), 0o600); err != nil {
74			t.Fatal(err)
75		}
76		if _, err := Load(path); !errors.Is(err, ErrUnsupportedVersion) {
77			t.Fatalf("err = %v", err)
78		}
79		if _, err := Load(filepath.Join(t.TempDir(), "missing.json")); !errors.Is(err, os.ErrNotExist) {
80			t.Fatalf("missing file: %v", err)
81		}
82	}
