229	// UsageTotal adds up a subscription's usage at times in [from, to).
230	func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
231		s.mu.Lock()
232		defer s.mu.Unlock()
233		var n int64
234		for _, u := range s.usage {
235			if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
236				n += u.Quantity
237			}
238		}
239		return n
240	}
