// Package snapshot saves the store to a JSON file and loads it back, so the server keeps its data across restarts. The
// file carries a version; files written by older versions of Tally are migrated when they are loaded, and Upgrade
// rewrites them in the current version.
package snapshot

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Version 3 keeps the invoice numbers and each organization's next number in the state.
type fileV3 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Save writes everything in st to path. The file is replaced atomically, so path is never left half-written.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := encode(st.Export(), now)
	if err != nil {
		return err
	}
	return writeAtomic(path, b)
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	st, err := decode(path, b)
	if err != nil {
		return nil, err
	}
	return store.FromState(st)
}

// Upgrade rewrites the snapshot at path as the current version. The original is first copied byte for byte to
// "<path>.v<old version>.bak", which must not exist yet. A file of the current version is left alone; a file of a newer
// version fails with ErrUnsupportedVersion and is left alone too.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	version, err := versionOf(path, b)
	if err != nil {
		return err
	}
	if version == Version {
		return nil
	}
	st, err := decode(path, b)
	if err != nil {
		return err
	}
	if _, err := store.FromState(st); err != nil {
		return fmt.Errorf("snapshot %s: %w", path, err)
	}
	if err := writeNew(fmt.Sprintf("%s.v%d.bak", path, version), b); err != nil {
		return err
	}
	out, err := encode(st, time.Now())
	if err != nil {
		return err
	}
	return writeAtomic(path, out)
}

// versionOf returns the version a snapshot file says it is.
func versionOf(path string, b []byte) (int, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return 0, fmt.Errorf("snapshot %s: %w", path, err)
	}
	return head.Version, nil
}

// decode returns the state in the snapshot b, read from path, migrated to the current version's form.
func decode(path string, b []byte) (store.State, error) {
	version, err := versionOf(path, b)
	if err != nil {
		return store.State{}, err
	}
	var st store.State
	switch version {
	case 1:
		if st, err = migrateV1(b); err != nil {
			return store.State{}, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
		numberInvoices(&st)
	case 2:
		var f fileV2
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
		numberInvoices(&st)
	case 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, fmt.Errorf("snapshot %s: %w", path, err)
		}
		st = f.State
	default:
		return store.State{}, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, version)
	}
	return st, nil
}

// numberInvoices gives the invoices of a snapshot older than version 3 their numbers: per organization, in creation order
// (created_at, then ID), from INV-000001. It also sets each organization's next number.
func numberInvoices(st *store.State) {
	order := make([]int, len(st.Invoices))
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(a, b int) bool {
		x, y := st.Invoices[order[a]], st.Invoices[order[b]]
		if !x.CreatedAt.Equal(y.CreatedAt) {
			return x.CreatedAt.Before(y.CreatedAt)
		}
		return x.ID < y.ID
	})
	st.InvoiceNext = map[string]int{}
	for _, i := range order {
		org := st.Invoices[i].OrgID
		n := st.InvoiceNext[org]
		if n == 0 {
			n = 1
		}
		st.Invoices[i].Number = store.InvoiceNumber(n)
		st.InvoiceNext[org] = n + 1
	}
}

func encode(state store.State, now time.Time) ([]byte, error) {
	b, err := json.MarshalIndent(fileV3{Version: Version, SavedAt: now.UTC(), State: state}, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(b, '\n'), nil
}

// writeAtomic replaces the file at path with data. The data goes to a temporary file in the same folder, which is then
// renamed over path, so path holds either the old file or the whole new one. A failed write leaves no temporary file.
func writeAtomic(path string, data []byte) (err error) {
	f, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			f.Close()
			os.Remove(f.Name())
		}
	}()
	if _, err = f.Write(data); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	return os.Rename(f.Name(), path)
}

// writeNew writes data to a file that must not exist yet, so an existing backup is never overwritten.
func writeNew(path string, data []byte) error {
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	_, err = f.Write(data)
	if cerr := f.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		os.Remove(path)
	}
	return err
}

