func TestSaveWritesVersion3AndLeavesNoTemporaryFile(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
