	p, ok := st.Plan(o.ID, "plan_000005")
	if !ok || p.Currency != money.USD || p.UnitAmount != 1999 || p.UsageType != store.Licensed || !p.Active {
		t.Fatalf("plan = %+v", p)
	}
	if k, ok := st.APIKeyByToken("tly_00000000000000000000000000000003"); !ok || k.UserID != "usr_000002" {
		t.Fatalf("key = %+v", k)
	}
	inv, ok := st.Invoice(o.ID, "in_000007")
	if !ok || inv.Lines[0].UnitAmount != 1999 || inv.Status != store.InvoicePaid || inv.Number != "INV-000001" {
		t.Fatalf("invoice = %+v", inv)
	}
	next, err := st.CreateCustomer(o.ID, "New", "new@example.com", time.Now())
	if err != nil || next.ID == "cus_000004" || next.ID <= "cus_000008" {
		t.Fatalf("the next ID %q reuses an old one: %v", next.ID, err)
	}
}

func TestLoadVersion2NumbersInvoices(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := os.WriteFile(path, []byte(v2Snapshot), 0o600); err != nil {
		t.Fatal(err)
	}
	st, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	want := map[string]struct{ org, number string }{
		"in_000005": {"org_000001", "INV-000001"},
		"in_000006": {"org_000001", "INV-000002"},
		"in_000007": {"org_000001", "INV-000003"},
		"in_000008": {"org_000002", "INV-000001"},
	}
	for id, w := range want {
		inv, ok := st.Invoice(w.org, id)
