	next, err := st.CreateInvoice(newInvoice("org_000001", "cus_000003"), time.Now())
	if err != nil || next.Number != "INV-000004" {
		t.Fatalf("the next invoice is %q, want INV-000004: %v", next.Number, err)
	}
}

func TestInvoiceNumbersSurviveSaveAndLoad(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	a, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	b, _ := st.CreateOrg("B", store.OrgTeam, "UTC", 0, now)
	ca, _ := st.CreateCustomer(a.ID, "Ann", "ann@example.com", now)
	cb, _ := st.CreateCustomer(b.ID, "Ben", "ben@example.com", now)
	numberOf := func(s *store.Store, orgID, customerID string) string {
		inv, err := s.CreateInvoice(newInvoice(orgID, customerID), now)
		if err != nil {
			t.Fatal(err)
		}
		return inv.Number
	}
	for _, got := range []struct{ got, want string }{
		{numberOf(st, a.ID, ca.ID), "INV-000001"},
		{numberOf(st, a.ID, ca.ID), "INV-000002"},
		{numberOf(st, b.ID, cb.ID), "INV-000001"},
	} {
		if got.got != got.want {
			t.Fatalf("number %q, want %q", got.got, got.want)
		}
	}

	path := filepath.Join(t.TempDir(), "tally.json")
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if n := numberOf(got, a.ID, ca.ID); n != "INV-000003" {
		t.Fatalf("after a reload the next number is %q, want INV-000003", n)
	}
	if n := numberOf(got, b.ID, cb.ID); n != "INV-000002" {
		t.Fatalf("after a reload org B's next number is %q, want INV-000002", n)
	}
}

func TestSaveWritesVersion3AndLeavesNoTemporaryFile(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, now)
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", now)
	_, _ = st.CreateInvoice(newInvoice(o.ID, c.ID), now)

	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	if err := os.WriteFile(path, []byte("old contents"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Save(st, path, now); err != nil {
		t.Fatal(err)
	}
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if v, err := versionOf(path, b); err != nil || v != 3 {
		t.Fatalf("version = %d, %v; want 3", v, err)
	}
	if !bytes.Contains(b, []byte(`"number": "INV-000001"`)) || !bytes.Contains(b, []byte(`"invoice_next"`)) {
		t.Fatalf("the file lacks the invoice numbers:\n%s", b)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 || entries[0].Name() != "tally.json" {
		t.Fatalf("the folder holds %d entries, want only tally.json", len(entries))
	}
}

func TestUpgradeCopiesOriginalAndRewritesAsVersion3(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json")
	orig := []byte(v2Snapshot)
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	bak, err := os.ReadFile(path + ".v2.bak")
	if err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup is not a copy of the original: %v", err)
	}
	upgraded, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if v, err := versionOf(path, upgraded); err != nil || v != Version {
		t.Fatalf("version = %d, %v; want %d", v, err, Version)
	}
	st, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if inv, ok := st.Invoice("org_000001", "in_000007"); !ok || inv.Number != "INV-000003" {
		t.Fatalf("invoice = %+v", inv)
	}

	// A file of the current version is left alone, without a backup.
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	again, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(again, upgraded) {
		t.Fatalf("a version 3 file was rewritten: %v", err)
	}
	if _, err := os.Stat(path + ".v3.bak"); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a backup of a version 3 file: %v", err)
	}
}

