func TestUpgradeNeverOverwritesABackup(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json")
	orig := []byte(v2Snapshot)
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path+".v2.bak", []byte("earlier backup"), 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err == nil {
		t.Fatal("Upgrade overwrote an existing backup")
	}
	if b, err := os.ReadFile(path); err != nil || !bytes.Equal(b, orig) {
		t.Fatalf("the snapshot changed: %v", err)
	}
	if b, err := os.ReadFile(path + ".v2.bak"); err != nil || string(b) != "earlier backup" {
		t.Fatalf("the backup changed: %v", err)
	}
}

func TestUpgradeRefusesNewerVersions(t *testing.T) {
	path := filepath.Join(t.TempDir(), "future.json")
	orig := []byte(`{"version": 4, "state": {}}`)
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if b, err := os.ReadFile(path); err != nil || !bytes.Equal(b, orig) {
		t.Fatalf("the file changed: %v", err)
	}
	if _, err := os.Stat(path + ".v4.bak"); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a backup of a newer file: %v", err)
	}
}

func TestLoadRefusesUnknownVersions(t *testing.T) {
	path := filepath.Join(t.TempDir(), "future.json")
	if err := os.WriteFile(path, []byte(`{"version": 9, "state": {}}`), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := Load(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if _, err := Load(filepath.Join(t.TempDir(), "missing.json")); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("missing file: %v", err)
	}
}

